cd /workspace && cat > tools/tracecheck.py <<'PY'
"""Independent trace-level audit of service replies (written from PROTOCOL.md).

Maintains its own model of revision/time/leases and validates every reply:
exact field sets, codes, audit samples, expired/cancelled arrays and all
certificates (plans, capacity witnesses, cut witnesses, block witnesses).
"""
from checkcert import valid_plan, valid_cut, valid_capacity


SHAPE = {
    'invalid': {'status'},
    'ok+protocol': {'status', 'protocol'},
    'ok+load': {'status', 'rev', 'now'},
    'ok+audit': {'status', 'rev', 'now', 'leases', 'samples'},
    'ok+advance': {'status', 'rev', 'now', 'expired'},
    'ok+edit': {'status', 'rev', 'cancelled'},
    'ok+commit': {'status', 'id', 'rev', 'replay'},
    'ok+cancel': {'status', 'rev', 'released'},
    'error': {'status', 'code', 'rev'},
    'stale': {'status', 'rev'},
    'blocked': {'status', 'rev', 'link', 'time', 'used', 'capacity'},
    'prepared': {'status', 'id', 'rev', 'plan'},
    'denied-cap': {'status', 'id', 'rev', 'kind', 'link', 'time', 'used', 'capacity'},
    'denied-cut': {'status', 'id', 'rev', 'kind', 'cut'},
    'replay': {'status', 'id', 'rev', 'base_rev', 'outcome'},
}


class Model:
    def __init__(self):
        self.loaded = False
        self.rev = 0
        self.time = 0
        self.n = 0
        self.links = []
        self.caps = []
        self.leases = {}
        self.dead = set()
        self.preps = {}

    def used(self, l, t):
        total = 0
        for rec in self.leases.values():
            if rec['s'] <= t < rec['e']:
                total += rec['env'].get(l, 0)
        return total


def audit(requests, replies):
    m = Model()
    problems = []
    for i, (req, got) in enumerate(zip(requests, replies)):
        def bad(msg):
            problems.append(f'[{i}] {req if not isinstance(req,dict) else req.get("op")} {msg}: {str(got)[:220]}')
        if not isinstance(got, dict) or 'status' not in got:
            bad('no status')
            continue
        st = got['status']
        keys = set(got)
        op = req.get('op') if isinstance(req, dict) else None
        if st == 'invalid':
            if keys != SHAPE['invalid']:
                bad('invalid shape')
            continue
        if op is None or not isinstance(op, str):
            bad('reply to non-object must be invalid')
            continue
        # ---- shape and unloaded checks
        if st == 'ok' and 'protocol' in got:
            if keys != SHAPE['ok+protocol'] or got['protocol'] != 'forest-controller/3' or op != 'about':
                bad('about shape')
            continue
        if op == 'load':
            if not m.loaded:
                if keys != SHAPE['ok+load'] or got['rev'] != 0 or got['now'] != 0:
                    bad('first load shape')
                # structural validity assumed
                m.loaded = True
                m.n = req.get('n', 0)
                m.links = [(u, v, c) for (u, v, c) in req.get('links', [])]
                m.caps = [c for (_u, _v, c) in m.links]
                m.rev = 0
                m.time = 0
                m.leases = {}
                for b in req.get('bookings', []):
                    env = dict(b['envelope'])
                    m.leases[b['id']] = {'owner': b['owner'], 's': b['window'][0],
                                         'e': b['window'][1], 'env': env}
            else:
                if keys != SHAPE['error'] or got['code'] != 'ALREADY_LOADED' or got['rev'] != m.rev:
                    bad('second load')
            continue
        if not m.loaded:
            if keys != SHAPE['error'] or got.get('code') != 'NOT_LOADED' or got.get('rev') != 0:
                bad('not loaded reply')
            continue
        if st == 'stale':
            if keys != SHAPE['stale'] or got['rev'] != m.rev:
                bad('stale shape')
            continue
        if st == 'error':
            if keys != SHAPE['error'] or got['rev'] != m.rev:
                bad('error shape')
            elif got['code'] not in ('TIME', 'REFERENCE', 'WINDOW', 'MISSING', 'OWNER',
                                     'DENIED', 'GONE', 'CONFLICT', 'NOT_LOADED',
                                     'ALREADY_LOADED'):
                bad('unknown code')
            continue
        if st == 'blocked':
            if keys != SHAPE['blocked'] or got['rev'] != m.rev:
                bad('blocked shape')
            else:
                l, t, u, c = got['link'], got['time'], got['used'], got['capacity']
                if not (t >= m.time):
                    bad('blocked time before now')
                if c != m.newcap if hasattr(m, 'newcap') else None:
                    pass
            continue
        if st == 'replay':
            if keys != SHAPE['replay'] or got['rev'] != m.rev:
                bad('replay shape')
            elif got['id'] != req['id'] or got['outcome'] not in ('prepared', 'denied'):
                bad('replay fields')
            continue
        if st == 'prepared':
            if keys != SHAPE['prepared'] or got['rev'] != m.rev:
                bad('prepared shape')
            else:
                demands = dict(req['participants'])
                env = dict(req['envelope'])
                ok, msg = valid_plan(m.n, m.links, demands, req['period'], env, got['plan'])
                if not ok:
                    bad(f'INVALID PLAN: {msg}')
                m.preps[req['id']] = {'outcome': 'prepared', 'base_rev': m.rev,
                                      'owner': req['owner'], 'window': tuple(req['window']),
                                      'env': env}
            continue
        if st == 'denied':
            if got['kind'] == 'capacity':
                if keys != SHAPE['denied-cap'] or got['rev'] != m.rev:
                    bad('denied capacity shape')
                else:
                    w = {'link': got['link'], 'time': got['time'], 'used': got['used'],
                         'capacity': got['capacity']}
                    ok, msg = valid_capacity(m.links, m.caps, m.used, req['period'],
                                             dict(req['envelope']), req['window'][0],
                                             req['window'][1], w)
                    if not ok:
                        bad(f'INVALID CAPACITY WITNESS: {msg}')
            else:
                if keys != SHAPE['denied-cut'] or got['rev'] != m.rev:
                    bad('denied cut shape')
                else:
                    ok, msg = valid_cut(m.n, m.links, dict(req['participants']),
                                        req['period'], dict(req['envelope']), got['cut'])
                    if not ok:
                        bad(f'INVALID CUT: {msg}')
            m.preps[req['id']] = {'outcome': 'denied', 'base_rev': m.rev,
                                  'owner': req['owner']}
            continue
        if st == 'ok':
            if op == 'audit':
                if keys != SHAPE['ok+audit'] or got['rev'] != m.rev or got['now'] != m.time:
                    bad('audit shape')
                else:
                    if got['leases'] != sorted(m.leases):
                        bad(f'audit leases {got["leases"]} != {sorted(m.leases)}')
                    want = []
                    for t in req['at']:
                        if t < m.time:
                            want = None
                            break
                        want.append([t, [m.caps[l] - m.used(l, t) for l in range(len(m.links))]])
                    if want is None:
                        if got['status'] != 'ok':
                            bad('audit TIME')
                    elif got['samples'] != want:
                        bad(f'audit samples {got["samples"]} != {want}')
                continue
            if op == 'advance':
                if keys != SHAPE['ok+advance']:
                    bad('advance shape')
                else:
                    t = req['time']
                    gone = sorted(i2 for i2, r in m.leases.items() if r['e'] <= t)
                    if got['expired'] != gone:
                        bad(f'advance expired {got["expired"]} != {gone}')
                    if got['rev'] != m.rev + 1 or got['now'] != t:
                        bad(f'advance rev/now {got["rev"]}/{got["now"]}')
                    for i2 in gone:
                        del m.leases[i2]
                        m.dead.add(i2)
                    m.time = t
                    m.rev += 1
                continue
            if op == 'edit':
                if keys != SHAPE['ok+edit'] or got['rev'] != m.rev + 1:
                    bad(f'edit shape/rev {got}')
                else:
                    newc = dict(zip(range(len(m.caps)), m.caps))
                    for (l, c) in req['changes']:
                        newc[l] = c
                    if req['force']:
                        dec = [l for (l, c) in req['changes'] if c < m.caps[l]]
                        rev_ids = sorted(i2 for i2, r in m.leases.items()
                                         if any(r['env'].get(l, 0) > 0 for l in dec))
                        if got['cancelled'] != rev_ids:
                            bad(f'edit cancelled {got["cancelled"]} != {rev_ids}')
                        for i2 in rev_ids:
                            del m.leases[i2]
                            m.dead.add(i2)
                    else:
                        if got['cancelled'] != []:
                            bad('nonforced cancelled')
                    m.caps = [newc[l] for l in range(len(newc))]
                    m.rev += 1
                continue
            if op == 'commit':
                if keys != SHAPE['ok+commit'] or got['id'] != req['id']:
                    bad('commit shape')
                else:
                    p = m.preps.get(req['id'])
                    if got['replay']:
                        if got['rev'] != m.rev:
                            bad('commit replay rev')
                    else:
                        if p is None or p['outcome'] != 'prepared' or p['base_rev'] != m.rev \
                                or req['rev'] != m.rev:
                            bad('commit should not succeed')
                        if got['rev'] != m.rev + 1:
                            bad('commit rev')
                        rec = p
                        m.leases[req['id']] = {'owner': req['owner'], 's': rec['window'][0],
                                               'e': rec['window'][1], 'env': dict(rec['env'])}
                        m.rev += 1
                continue
            if op == 'cancel':
                if keys != SHAPE['ok+cancel'] or got['rev'] != m.rev + 1 or \
                        got['released'] != req['id']:
                    bad(f'cancel shape/rev {got}')
                else:
                    if req['id'] not in m.leases:
                        bad('cancel of non live id')
                    else:
                        del m.leases[req['id']]
                        m.dead.add(req['id'])
                    m.rev += 1
                continue
            bad(f'unexpected ok reply for {op}')
        else:
            bad('unknown status')
    return problems
PY
echo ok
